ntity_type], [Name], [Version_ID_or_operation_ID])) as [Operation_ID], 			convert(varchar(100),[Version_ID_or_operation_ID]), 			[Name], 			[POS_name], 			[Kitchen_name], 			[Item_description], 			[Price], 			[PLU], 			[SKU], 			convert(varchar(100),[Sales_category_multiLocation_ID]) 		from #Staging 		order by Sort, [Operation_ID]  		drop table #Staging                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine;         THROW;     END CATCH END